contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put with an unlock time and an amount sent.
    // Params: uint unlockTime, uint amount
    function run(uint _unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Observe balance before
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put sending `amount` wei
        c.Put{value: amount}(_unlockTime);

        // Observe after
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule: if Put succeeded (it did not revert because call returned),
        // then the contract's stored balance for this address increased by exactly `amount`
        // and the contract's Ether balance increased by exactly `amount`.
        // Also, Put cannot reduce the stored balance: afterBalance >= beforeBalance.
        assert(afterBalance == beforeBalance + amount && afterContractBal == beforeContractBal + amount && afterBalance >= beforeBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // uint depositAmount: amount to deposit via Put
    // uint unlockDelta: seconds to add to current block.timestamp to set unlock time
    // uint collectAmount: amount to attempt to Collect
    function run(uint depositAmount, uint unlockDelta, uint collectAmount) public payable {
        // ensure this test contract can send depositAmount when calling Put
        require(address(this).balance >= depositAmount);

        // initial observations
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // make a deposit so there is something to collect later
        // send depositAmount wei to c with unlock time in the future (so Collect may require time)
        uint unlockTime = block.timestamp + unlockDelta;
        c.Put{value: depositAmount}(unlockTime);

        // observe after deposit
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Try to Collect collectAmount. We capture whether it reverted.
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after collect attempt
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // - If Collect reverted, nothing changed as a result of Collect: stored balance and contract balance remain as after the Put.
        // - If Collect succeeded, then the contract's Ether balance decreased by exactly the decrease in stored balance for this caller,
        //   and that decrease is <= collectAmount (it never transfers more than requested).
        // Note: we compare mid* (state after Put) to after* (state after Collect attempt).
        assert(
            (reverted && afterBalance == midBalance && afterContractBal == midContractBal)
            || (
                !reverted
                && midBalance >= afterBalance
                && midContractBal >= afterContractBal
                && (midBalance - afterBalance) == (midContractBal - afterContractBal)
                && (midBalance - afterBalance) <= collectAmount
            )
        );
    }

    // receive to accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // uint depositAmount: amount to deposit via Put
    // uint unlockDelta: seconds to add to current block.timestamp to set unlock time for the deposit
    // uint collectAmount: amount to attempt to Collect
    function run(uint depositAmount, uint unlockDelta, uint collectAmount) public payable {
        // ensure this test contract can send depositAmount when calling Put
        require(address(this).balance >= depositAmount);

        // read MinSum to use in the property
        uint minSum = c.MinSum();

        // capture before state
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // make a deposit with unlock time = now + unlockDelta
        uint unlockTime = block.timestamp + unlockDelta;
        c.Put{value: depositAmount}(unlockTime);

        // read state after deposit
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // attempt Collect and detect whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read state after collect attempt
        (uint finalUnlock, uint finalBal) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // If Collect succeeded (not reverted) then:
        //  - caller's pre-Collect stored balance (afterBal) must have been >= minSum
        //  - caller's pre-Collect stored balance (afterBal) must have been >= collectAmount
        //  - block.timestamp must have been > unlock time set on the deposit (afterUnlock)
        //  - both stored balance and contract balance decreased by the same amount delta > 0
        //  - the delta is <= collectAmount
        // If Collect reverted then no change to balances/state occurred by Collect (final == after)
        assert(
            (reverted && finalBal == afterBal && finalContractBal == afterContractBal)
            || (
                !reverted
                && afterBal >= minSum
                && afterBal >= collectAmount
                && block.timestamp > afterUnlock
                && finalBal <= afterBal
                && finalContractBal <= afterContractBal
                && (afterBal - finalBal) == (afterContractBal - finalContractBal)
                && (afterBal - finalBal) > 0
                && (afterBal - finalBal) <= collectAmount
            )
        );
    }

    // receive to accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // uint depositAmount: amount to deposit via Put
    // uint unlockTime: unlock time argument passed to Put
    function run(uint depositAmount, uint unlockTime) public payable {
        // ensure this test contract can send depositAmount when calling Put
        require(address(this).balance >= depositAmount);

        // observe before state for this caller
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform the deposit via Put with specified unlockTime and value depositAmount
        c.Put{value: depositAmount}(unlockTime);

        // observe after state
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // The general invariant: the increase in the recorded stored balance equals the increase in the contract's Ether balance
        // i.e., afterBal - beforeBal == afterContractBal - beforeContractBal
        // Use <= comparisons to avoid underflow in case values didn't increase; express equality safely
        assert(
            (afterBal >= beforeBal && afterContractBal >= beforeContractBal && (afterBal - beforeBal) == (afterContractBal - beforeContractBal))
            || (afterBal == beforeBal && afterContractBal == beforeContractBal)
        );
    }

    // accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // uint depositAmount: amount to deposit via Put
    // uint unlockTime: unlock time argument passed to Put
    // uint withdrawReq: requested amount passed to Collect
    function run(uint depositAmount, uint unlockTime, uint withdrawReq) public payable {
        // ensure this test contract can send depositAmount when calling Put
        require(address(this).balance >= depositAmount);

        // Observe before state for this caller via public getter
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform deposit so caller may have funds (Put is payable)
        c.Put{value: depositAmount}(unlockTime);

        // Now attempt Collect and record whether it reverted and the contract balance after
        bool reverted;
        uint afterContractBal;
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        try c.Collect{value: 0}(withdrawReq) {
            reverted = false;
        } catch {
            reverted = true;
        }
        afterContractBal = address(c).balance;
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // If Collect succeeded (not reverted), then the decrease in the stored balance is at least
        // the decrease in the contract's ETH balance, and the contract's ETH balance decreased by
        // exactly the transferred amount. Because we cannot directly observe the transferred
        // amount, we assert that if not reverted then:
        //   beforeContractBal >= afterContractBal (contract balance did not increase)
        //   beforeBal >= afterBal (stored balance did not increase)
        //   (beforeContractBal - afterContractBal) <= (beforeBal - afterBal)
        // The idea: the recorded balance should cover the ETH outflow; stored balance decreases by
        // at least the ETH actually sent.
        assert(
            reverted
            || (
                beforeContractBal >= afterContractBal
                && beforeBal >= afterBal
                && (beforeContractBal - afterContractBal) <= (beforeBal - afterBal)
            )
        );
    }

    // accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will perform: Put with some unlockTime and value, then attempt Collect of amount am.
    // The rule: if Put does not revert and Collect does not revert and Collect returns (i.e., does not revert),
    // then Acc[this].balance decreases by am and address(c).balance decreases by am.
    function run(uint unlockTime, uint am, uint deposit) public payable {
        require(address(this).balance >= deposit, "insufficient test balance");
        // Make a Put call sending `deposit` wei. This must be a top-level state-changing call.
        bool putReverted;
        try c.Put{value: deposit}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read balance observed in c for this contract address after Put (public getter Acc)
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Try Collect; capture whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If both Put and Collect succeeded, then recorded balance decreased by exactly am
        // and contract's Ether balance decreased by exactly am. If Collect reverted or Put reverted,
        // we do not require the decrease. This is a general invariant about successful flows.
        assert(putReverted || collectReverted || (beforeBalance >= am && afterBalance + am == beforeBalance && afterContractBal + am == beforeContractBal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: optionally deposit via Put, then attempt Collect of amount am.
    // The property: whenever Collect call returns (does not revert), the Acc[this].balance after the call is strictly less than before.
    function run(uint unlockTime, uint am, uint deposit) public payable {
        require(address(this).balance >= deposit, "insufficient test balance");

        // Make an initial Put to ensure there may be funds; ignore if it reverts.
        bool putReverted;
        try c.Put{value: deposit}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read recorded balance before Collect.
        (, uint beforeBalance) = c.Acc(address(this));

        // Attempt Collect and record whether it reverted.
        bool collectReverted;
        try c.Collect{value: 0}(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (, uint afterBalance) = c.Acc(address(this));

        // If Collect did not revert, then afterBalance must be strictly less than beforeBalance.
        // Note: this is a general rule about successful Collect reducing the recorded balance.
        assert(collectReverted || afterBalance < beforeBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will optionally deposit via Put, then attempt Collect(am).
    // Property: If Collect does not revert, the contract's Ether balance decreases by >= am.
    // Inputs:
    //  - unlockTime: parameter passed to Put
    //  - deposit: Ether sent to Put (must be available in this contract)
    //  - am: amount requested in Collect
    function run(uint unlockTime, uint deposit, uint am) public payable {
        require(address(this).balance >= deposit, "insufficient test balance");

        // Record contract balance before any interaction
        uint beforeContractBal = address(c).balance;

        // Try to deposit via Put; ignore if it reverts
        bool putReverted;
        try c.Put{value: deposit}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Record contract balance after Put and before Collect
        uint midContractBal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Record contract balance after Collect
        uint afterContractBal = address(c).balance;

        // If Collect succeeded, then the contract's balance must have decreased by at least am
        // (i.e., before the Collect call it had at least am more than after).
        // Use midContractBal as the immediate pre-Collect observable balance.
        assert(collectReverted || midContractBal >= afterContractBal + am);
    }

    receive() external payable {}
}
